const readonlyBefore=db('V01-before');await nav('quoteImport');await p.locator('#quoteImportSupplier').selectOption('U46-A');await p.locator('#quoteRoundSelect').selectOption('2|1');await p.locator('[data-srm-ux-input-mode="file"]').click();
for(const[width,height]of [[1024,768],[1366,768],[1600,900]]){
 await p.setViewportSize({width,height});for(const id of ['#uiProjectDetails','#uiSupplierTools','#uiDataTools','#uiDrawingTools'])await close(id);
 for(const section of ['items','assign','quoteImport','quotes','settings']){
  await nav(section);await p.locator('#srmV3PageStage-'+section+' h2').scrollIntoViewIfNeeded();const layout=await p.evaluate(()=>({viewport:{width:innerWidth,height:innerHeight},documentWidth:document.documentElement.scrollWidth,active:document.querySelector('section.panel.active').id,save:document.querySelector('#srmUxWorkspaceSaveSummary').textContent,rfq:document.querySelector('#uiCurrentRfq').textContent,tables:[...document.querySelectorAll('section.panel.active .tablewrap')].filter(e=>e.clientWidth).map(e=>({clientWidth:e.clientWidth,scrollWidth:e.scrollWidth,overflowX:getComputedStyle(e).overflowX})),visibleButtons:[...document.querySelectorAll('section.panel.active button')].filter(e=>e.offsetWidth&&e.offsetHeight).map(e=>({id:e.id,text:e.textContent.trim(),left:e.getBoundingClientRect().left,right:e.getBoundingClientRect().right}))}));
  await check('V01 '+width+' '+section+' no document overflow',layout.documentWidth<=width,true);log('UI-layout',{width,height,section,layout});await shot('V01-'+width+'-'+section);
  if(section==='quoteImport'){
   await p.locator('#quoteRoundBody tr').first().scrollIntoViewIfNeeded();const metrics=await p.locator('#quoteRoundBody tr').evaluateAll(es=>es.slice(0,6).map(e=>({height:e.getBoundingClientRect().height,font:getComputedStyle(e.querySelector('td')).fontSize,text:e.querySelector('td').innerText})));log('compact-row-measures',{width,height,metrics});await shot('V01-'+width+'-quote-compact');await p.locator('#quoteRoundBody [data-srm-ux-line-detail="0"]').click();await p.locator('#srmUxQuoteLineDetail').scrollIntoViewIfNeeded();await shot('V01-'+width+'-quote-details');await p.locator('#srmUxQuoteDensity').click();await p.locator('#srmUxQuoteRoundTable').evaluate(e=>{e.closest('.tablewrap').scrollLeft=e.scrollWidth});const sticky=await p.locator('#quoteRoundBody tr').first().locator('td').first().evaluate(e=>({position:getComputedStyle(e).position,left:e.getBoundingClientRect().left,wrap:e.closest('.tablewrap').getBoundingClientRect().left,text:e.innerText}));await check('V01 '+width+' sticky RFQ identity after horizontal scroll',sticky.position==='sticky'&&sticky.left>=sticky.wrap-3&&sticky.left<=sticky.wrap+5,true);log('sticky-identity',{width,sticky});await shot('V01-'+width+'-quote-full-scrolled');await p.locator('#srmUxQuoteDensity').click();
  }
  if(section==='quotes'){
   await p.locator('#quoteTable').scrollIntoViewIfNeeded();await shot('V01-'+width+'-comparison-matrix');await p.locator('#quoteAnalysis').scrollIntoViewIfNeeded();await shot('V01-'+width+'-comparison-analysis');await p.locator('#srmUxPendingOnly').check();await check('V01 '+width+' pending filter retains9',await p.locator('#quoteTable tbody tr').count(),9);await p.locator('#srmUxPendingOnly').uncheck();
  }
 }
 await p.locator('[data-srm-v2-action="admin"]').click();await p.locator('#pilotS4DownloadFull').scrollIntoViewIfNeeded();await check('V01 '+width+' actual S4 control reachable',await p.locator('#pilotS4DownloadFull').isVisible()&&await p.locator('#pilotS4DownloadFull').isEnabled(),true);await shot('V01-'+width+'-backup-actions');await close('#uiDataTools');await p.locator('[data-srm-v2-tab="quotes"]').focus();await p.keyboard.press('Enter');await check('V01 '+width+' keyboard sidebar activation',await p.locator('section.panel.active').getAttribute('id'),'quotes');log('keyboard-focus',{width,outline:await p.locator('[data-srm-v2-tab="quotes"]').evaluate(e=>getComputedStyle(e).outline)});
}
await saved();await check('V01 all view changes preserve SQLite/history/PDF',db('V01-after'),readonlyBefore);await check('V01 original selected RFQ preserved',(await snap()).workspaceId,wid);await shot('V01-completed');log('case-complete',{id:'V01',status:'PASS',note:'Functional geometry checks; independent visual/usability review reported separately, not pixel certification'});await context.tracing.stop({path:root+'independent-trace.zip'});await browser.close();await stopServer(server);fs.writeFileSync(root+'run-complete.json',JSON.stringify({productSHA:'c2737f0221a7b529114da2df363e062e75c7544c',browserRunComplete:true,driverCorrections:0},null,2));global.stopped=true;console.log('INDEPENDENT_SCOPE_COMPLETE');
